optionalDelta.css:
/* Review-only addition to frozen V37. Public route uses canonical bibliography. */
@media screen {
  .sources li > a {
    display: inline-block;
    min-width: 24px;
    min-height: 24px;
    max-width: 100%;
    padding-block: 3px;
    vertical-align: top;
  }
}
@media screen and (max-width: 480px) {
  .sources li > a {
    display: block;
    width: fit-content;
  }
  .sources .return { margin-left: 0; }
}
